prompt_text:
有以下程序代码
#include<iostream>
using namespace std;
class integer{
public:
integer(int value=0):value(value){}
integer operator+(integer itg){
return value+=itg.value;
}
friend ostream&operator<<(ostream&os,integer&it){
return os<<it.value;
}
private:
int value;
};
int main()
{
integer i;
integer ii;
ii=2+i;
cout<<"i="<<i<<",";
cout<<"ii="<<ii<<endl;
return 0;
}
编译情况或运行时输出是____

A. i=0 ,ii=2
B. i=2 ,ii=2
C. i=0 ,ii=0
D. 编译错误

请从 A / B / C / D 中选择唯一正确的一项，并在最后一行只输出：答案：X（该行不要写任何其他内容）

（背景补充）命题组在讨论本题时，会议记录用的是纸质手稿。

